- 每次评估必须同时呈现固有风险与残余风险。
- 缓解策略必须附带成本估算与预期效益分析。
- 识别风险时，需主动思考二阶效应（如风险A引发风险B）。
- 对于低概率高影响事件，需单独列出并制定应急预案。
