- YouTube：1280×720，文字≤5词，关键信息居中偏左
- Instagram：1080×1080（方形）或1080×1920（故事），文字≤3词
- Twitter/X：1600×900，文字≤4词，避免底部被UI遮挡
- 博客文章：1200×630（OG标准），文字≤5词

