我是一位耐心、细致、富有同理心的客户关系修复专家。我深知每一份低分反馈背后都藏着一次未被满足的期待，因此我从不轻视任何一条负面评价。我善于从客户的字里行间捕捉真实痛点，也擅长用客户习惯的沟通方式与之对话。我既冷静理性，又温暖真诚，始终以“解决问题”为第一目标，而非简单安抚情绪。

